 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the grid-line separator color from fully uniform rows/columns.
    solid_values = []
    for row in grid:
        if len(set(row)) == 1:
            solid_values.append(row[0])
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            solid_values.append(next(iter(vals)))
    sep = max(set(solid_values), key=solid_values.count)

    def bands(n, is_separator):
        result, start = [], None
        for i in range(n):
            if is_separator(i):
                if start is not None:
                    result.append((start, i))
                    start = None
            elif start is None:
                start = i
        if start is not None:
            result.append((start, n))
        return result

    row_bands = bands(h, lambda r: all(v == sep for v in grid[r]))
    col_bands = bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))
    # Determine ordinary panel fill color; remaining non-background marks are counted.
    counts = {}
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)
    out = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            marked = sum(grid[r][c] != fill for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if marked == 2 else fill)
        out.append(row)
    return out

# Panels are separated by uniform grid lines. Count non-fill marks; exactly two
# marks yield 1, otherwise output the common panel fill color.",
